module tb_TopModule;

    logic       clk;
    logic       areset;
    logic       train_valid;
    logic       train_taken;
    logic [1:0] state;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .train_valid(train_valid),
        .train_taken(train_taken),
        .state(state)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        train_valid = 0;
        train_taken = 0;
        #12;
        areset = 0;

        // Check reset value
        if (state !== 2'b01) begin
            $display("SELFTEST FAIL: Reset state incorrect. Expected 01, got %b", state);
            $finish;
        end

        // Test holding value when train_valid = 0
        @(posedge clk);
        train_valid = 0;
        train_taken = 1;
        #2;
        if (state !== 2'b01) begin
            $display("SELFTEST FAIL: Changed value when train_valid=0");
            $finish;
        end

        // Test incrementing up to 3 (1 -> 2 -> 3 -> 3)
        @(posedge clk);
        train_valid = 1;
        train_taken = 1;
        #2;
        if (state !== 2'b10) begin $display("SELFTEST FAIL: Inc 1->2 failed, got %b", state); $finish; end

        @(posedge clk);
        #2;
        if (state !== 2'b11) begin $display("SELFTEST FAIL: Inc 2->3 failed, got %b", state); $finish; end

        // Saturate at 3
        @(posedge clk);
        #2;
        if (state !== 2'b11) begin $display("SELFTEST FAIL: Saturation at 3 failed, got %b", state); $finish; end

        // Test decrementing down to 0 (3 -> 2 -> 1 -> 0 -> 0)
        train_taken = 0;
        @(posedge clk);
        #2;
        if (state !== 2'b10) begin $display("SELFTEST FAIL: Dec 3->2 failed, got %b", state); $finish; end

        @(posedge clk);
        #2;
        if (state !== 2'b01) begin $display("SELFTEST FAIL: Dec 2->1 failed, got %b", state); $finish; end

        @(posedge clk);
        #2;
        if (state !== 2'b00) begin $display("SELFTEST FAIL: Dec 1->0 failed, got %b", state); $finish; end

        // Saturate at 0
        @(posedge clk);
        #2;
        if (state !== 2'b00) begin $display("SELFTEST FAIL: Saturation at 0 failed, got %b", state); $finish; end

        // Asynchronous reset test mid-operation
        train_valid = 1;
        train_taken = 1;
        #3;
        areset = 1;
        #3;
        if (state !== 2'b01) begin $display("SELFTEST FAIL: Async reset failed mid-op, got %b", state); $finish; end
        areset = 0;

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
